import{_ as r,c as a,o as t,a5 as i}from"./chunks/framework.CnICWABh.js";const u=JSON.parse('{"title":"Devices","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices.md","filePath":"devices.md"}'),o={name:"devices.md"};function s(c,e,d,n,l,h){return t(),a("div",{"data-pagefind-body":!0},e[0]||(e[0]=[i('<h1 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h1><p>We make a range of GPS tracking devices for different applications, split into three main categories: Core, RTK, and Custom.</p><p>All of our devices are designed and made in the UK from the same modular components, and are available to purchase via a <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">sales enquiry</a>.</p><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><p>Our core products have been rigorously tested in the field since and iterated on since 2015, are used by customers around the world.</p><div class="device-gallery core-gallery"><div class="device-item"><a href="/devices/zero/"><img src="https://upload.r2.lb.chasm.cloud/2025/10/product-front/LB-DEV-ZE2.png" alt="Zero GPS Tracker"></a><p><strong>Zero</strong> - Our smallest GPS tracking device, and indeed one of the smallest in the world.</p></div><div class="device-item"><a href="/devices/pro/"><img src="https://upload.r2.lb.chasm.cloud/2025/10/product-front/LB-DEV-PR2.png" alt="Pro GPS Tracker"></a><p><strong>Pro</strong> - Our larger, industrial grade tracker.</p></div><div class="device-item"><a href="/devices/vehicle/"><img src="https://upload.r2.lb.chasm.cloud/2025/10/product-front/LB-DEV-VT3.png" alt="Vehicle GPS Tracker"></a><p><strong>Vehicle</strong> - Our wired tracker, designed for use where a power source is available.</p></div><div class="device-item"><a href="/devices/enviro/"><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/DlyOzj4.png" alt="Enviro GPS Tracker"></a><p><strong>Enviro</strong> - Like a pro, but with high accuracy built-in sensors for monitoring temperature, humidity and absolute pressure.</p></div></div><h2 id="rtk" tabindex="-1">RTK <a class="header-anchor" href="#rtk" aria-label="Permalink to &quot;RTK&quot;">​</a></h2><p>Our RTK products are designed for high accuracy applications, down to the centimetre, with the latest releases being made in 2025.</p><div class="device-gallery rtk-gallery"><div class="device-item"><a href="/devices/rtk/handheld"><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/5EtRBMH.png" alt="RTK GPS Tracker"></a><p><strong>RTK</strong> - Our high accuracy indoor and outdoor capable tracker.</p></div><div class="device-item"><a href="/devices/rtk/vehicle"><img src="https://upload.r2.lb.chasm.cloud/2025/10/product-front/LB-DEV-VT3.png" alt="RTK Vehicle GPS Tracker"></a><p><strong>RTK</strong> - Our high accuracy indoor and outdoor capable tracker, with wired power.</p></div></div><h2 id="custom" tabindex="-1">Custom <a class="header-anchor" href="#custom" aria-label="Permalink to &quot;Custom&quot;">​</a></h2><p>We also make <a href="/docs/pr/15/devices/custom">custom devices</a>, and have a number of devices that are <a href="/docs/pr/15/devices/history/">no longer in production</a>.</p>',11)]))}const v=r(o,[["render",s]]);export{u as __pageData,v as default};
